/* @lc app=leetcode id=3441 lang=kotlin */ class Solution { fun minCostGoodCaption(caption: String): String = caption.length.let { n -> if (n < 3) "" else Array(n + 1) { Array(26) { IntArray(4) { 1_000_000_000 } } }.also { F -> (0..25).forEach { c -> F[n][c][3] = 0 } }.also { F -> (n - 1 downTo 1).forEach { i -> (caption[i] - 'a').let { x -> (0..25).map { d -> Math.abs(x - d) + F[i + 1][d][1] }.let { g -> g.indices.minBy { g[it] }.let { a1 -> g.indices.filter { it != a1 }.minOf { g[it] }.let { m2 -> (0..25).forEach { c -> (1..3).forEach { r -> F[i][c][r] = minOf(1_000_000_000, Math.abs(x - c) + F[i + 1][c][minOf(3, r + 1)], if (r == 3) (if (a1 != c) g[a1] else m2) else 1_000_000_000) } } } } } } } }.let { F -> (caption[0] - 'a').let { x0 -> (0..25).map { d -> Math.abs(x0 - d) + F[1][d][1] }.let { c0 -> if (c0.min() >= 1_000_000_000) "" else generateSequence(Triple(1, c0.indexOf(c0.min()), 1)) { (i, c, r) -> if (i >= n) null else (caption[i] - 'a').let { x -> F[i][c][r].let { tg -> (0..25).first { d -> (if (d == c) Math.abs(x - c) + F[i + 1][c][minOf(3, r + 1)] else if (r == 3) Math.abs(x - d) + F[i + 1][d][1] else 1_000_000_000) == tg }.let { d -> Triple(i + 1, d, if (d == c) minOf(3, r + 1) else 1) } } } }.map { 'a' + it.second }.joinToString("") } } } } }